// Generateur Universel de Fichiers .SBP et .SBPCFG pour Satisfactory 1.0 (Navigateur & Node.js)
// Compatible Blueprint Designer Mk.1 (4x4), Mk.2 (5x5), Mk.3 (6x6)

class BlueprintBinaryWriter {
  constructor() {
    this.chunks = [];
  }
  writeInt8(val) { const b = new Uint8Array(1); new DataView(b.buffer).setInt8(0, val); this.chunks.push(b); }
  writeUInt8(val) { const b = new Uint8Array(1); new DataView(b.buffer).setUint8(0, val); this.chunks.push(b); }
  writeInt16(val) { const b = new Uint8Array(2); new DataView(b.buffer).setInt16(0, val, true); this.chunks.push(b); }
  writeInt32(val) { const b = new Uint8Array(4); new DataView(b.buffer).setInt32(0, val, true); this.chunks.push(b); }
  writeUInt32(val) { const b = new Uint8Array(4); new DataView(b.buffer).setUint32(0, val, true); this.chunks.push(b); }
  writeInt64(val) { const b = new Uint8Array(8); new DataView(b.buffer).setBigInt64(0, BigInt(val), true); this.chunks.push(b); }
  writeFloat(val) { const b = new Uint8Array(4); new DataView(b.buffer).setFloat32(0, val, true); this.chunks.push(b); }
  writeString(str) {
    if (!str || str.length === 0) { this.writeInt32(0); return; }
    const encoder = new TextEncoder();
    const encoded = encoder.encode(str + '\0');
    this.writeInt32(encoded.length);
    this.chunks.push(encoded);
  }
  writeBuffer(buf) {
    if (buf instanceof Uint8Array) { this.chunks.push(buf); }
    else { this.chunks.push(new Uint8Array(buf)); }
  }
  getUint8Array() {
    let totalLen = this.chunks.reduce((acc, c) => acc + c.length, 0);
    let result = new Uint8Array(totalLen);
    let offset = 0;
    for (let c of this.chunks) { result.set(c, offset); offset += c.length; }
    return result;
  }
}

async function compressZlib(uint8Arr) {
  if (typeof CompressionStream !== 'undefined') {
    const cs = new CompressionStream('deflate');
    const writer = cs.writable.getWriter();
    writer.write(uint8Arr);
    writer.close();
    const response = new Response(cs.readable);
    const arrayBuffer = await response.arrayBuffer();
    return new Uint8Array(arrayBuffer);
  } else if (typeof require !== 'undefined') {
    const zlib = require('zlib');
    return new Uint8Array(zlib.deflateSync(uint8Arr));
  }
  throw new Error('Compression non supportée sur cet environnement.');
}

async function packUEChunks(uncompressedFull) {
  const maxBlock = 131072;
  const numChunks = Math.ceil(uncompressedFull.length / maxBlock) || 1;
  const outChunks = [];
  for (let i = 0; i < numChunks; i++) {
    const start = i * maxBlock;
    const end = Math.min(start + maxBlock, uncompressedFull.length);
    const slice = uncompressedFull.subarray(start, end);
    const comp = await compressZlib(slice);
    const compLen = comp.length;
    const uncompLen = slice.length;
    const hdr = new BlueprintBinaryWriter();
    hdr.writeUInt32(0x9e2a83c1);
    hdr.writeUInt32(0x22222222);
    hdr.writeUInt32(131072);
    hdr.writeUInt32(0);
    hdr.writeUInt32((compLen << 8) | 3);
    hdr.writeUInt32(0);
    hdr.writeUInt32(uncompLen << 8);
    hdr.writeUInt32(0);
    hdr.writeUInt32(compLen << 8);
    hdr.writeUInt32(0);
    hdr.writeUInt32(uncompLen << 8);
    hdr.writeUInt32(0);
    hdr.writeInt8(0);
    hdr.writeBuffer(comp);
    outChunks.push(hdr.getUint8Array());
  }
  let totalLen = outChunks.reduce((acc, c) => acc + c.length, 0);
  let res = new Uint8Array(totalLen);
  let off = 0;
  for (let c of outChunks) { res.set(c, off); off += c.length; }
  return res;
}

function base64ToUint8(base64Str) {
  if (typeof Buffer !== 'undefined') {
    return new Uint8Array(Buffer.from(base64Str, 'base64'));
  }
  const binaryString = atob(base64Str);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) { bytes[i] = binaryString.charCodeAt(i); }
  return bytes;
}

